import{_ as e,o,c as d,a2 as a}from"./chunks/framework.BGlkWkwp.js";const b=JSON.parse('{"title":"Button","description":"","frontmatter":{},"headers":[],"relativePath":"components/button.md","filePath":"components/button.md"}'),n={name:"components/button.md"};function r(i,t,s,c,h,l){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="button" tabindex="-1">Button <a class="header-anchor" href="#button" aria-label="Permalink to &quot;Button&quot;">​</a></h1><p>Button is a control that is pressed to act.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for an action: <code>primary</code> for the one main action of a screen and the default <code>outline</code> for the others. <code>danger</code> marks an action that removes something and leads to a confirmation, whose own primary action is <code>danger-fill</code>. An icon button (<code>icon</code>, with an <code>aria-label</code>) is <code>ghost</code>; <code>ghost</code> is not used for text, since text without a line does not look pressable. An action that needs no line is a <a href="./link-action">LinkAction</a>. The children of a text button are text only: icons go in <code>leading</code> and <code>trailing</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>outline</code></td><td>The look, one of the five above</td></tr><tr><td><code>icon</code></td><td><code>false</code></td><td>A square button with an icon and no text</td></tr><tr><td><code>aria-label</code></td><td></td><td>The name of an icon button</td></tr><tr><td><code>leading</code></td><td></td><td>An icon before the text (a name or a component)</td></tr><tr><td><code>trailing</code></td><td></td><td>An icon after the text, such as a menu&#39;s chevron</td></tr><tr><td><code>mark</code></td><td></td><td>A mark of a value before the text (a snippet)</td></tr><tr><td><code>kbd</code></td><td></td><td>A key hint after the text</td></tr><tr><td><code>clamp</code></td><td><code>false</code></td><td>The trigger of a value</td></tr><tr><td><code>mono</code></td><td><code>false</code></td><td>The text in the monospace font</td></tr><tr><td><code>badge</code></td><td></td><td>A count over an icon button; 100 and more shows 99+</td></tr><tr><td><code>tip</code></td><td></td><td>The text of the tooltip; <code>false</code> turns it off</td></tr><tr><td><code>shortcut</code></td><td></td><td>A key hint inside the tooltip</td></tr><tr><td><code>on</code></td><td><code>false</code></td><td>Selected, as a tool in a toolbar</td></tr><tr><td><code>tone</code></td><td></td><td><code>danger</code>: a ghost button whose text turns red on hover</td></tr><tr><td><code>block</code></td><td><code>false</code></td><td>The full width, for the action of a one-column form</td></tr><tr><td><code>busy</code></td><td><code>false</code></td><td>An action in progress: disabled, with a progress cursor</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Not pressable</td></tr><tr><td><code>type</code></td><td><code>button</code></td><td><code>button</code> or <code>submit</code></td></tr><tr><td><code>href</code></td><td></td><td>Renders a link with the same look</td></tr><tr><td><code>target</code></td><td></td><td><code>_blank</code> opens the link in another tab</td></tr><tr><td><code>onclick</code></td><td></td><td>Called when pressed</td></tr><tr><td><code>children</code></td><td>required</td><td>The text, or the icon of an icon button</td></tr></tbody></table><p>Other attributes (<code>aria-*</code>, <code>data-*</code>) go to the element.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The height is the one the container declares for its controls (<code>--kata-box</code>), a button&#39;s by default: the ink of the text, pad-md above and below, and a line on each side. A list item or a toolbar declares the small button, with pad-sm above and below. The padding at the sides is pad-md and an icon is gap-sm from the text. An icon button is the square of a small button, wherever it is. The text is one line, trimmed to its ink; a button wider than its container shrinks and ends its text with an ellipsis. Hover shows the raise surface, pressing the stronger one; a disabled or busy button takes no hover. Disabled is the same shape without hue: a filled button (primary, danger-fill) takes the solid-disabled surface and its text and is not dimmed; a button with a line (outline, danger) takes the outline&#39;s text and line, and a ghost button the outline&#39;s text, dimmed. Busy looks the same as disabled and differs only in its cursor; the spinner of a running task belongs to what shows the task, not to the button. The area that is pressed, the hover surface, the line and the focus ring all belong to the button. A ghost button without a pressed state (neither <code>on</code> nor <code>aria-pressed</code> nor <code>aria-current</code>: a close button, the trigger of a menu, a chevron that opens) has no line or surface at rest: it is laid out as its icon, and the area that is pressed, the hover surface and the focus ring reach the control&#39;s height around it without taking room. A ghost button that shows whether it is chosen (a tool, a page) keeps its box. An icon button shows its <code>aria-label</code> in a <a href="./tooltip">Tooltip</a>, with <code>shortcut</code> as the key hint; a text button shows one only when <code>tip</code> is given.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/button/" title="Button" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/button/" target="_blank" rel="noopener">Button</a></figcaption></figure>',11)])])}const p=e(n,[["render",r]]);export{b as __pageData,p as default};
